// Pre-sign confirmation sheet: what you're signing, in plain English, with
// findings, balance changes, and the EIP-712 digests to compare against the
// KeepKey screen. Danger findings require typing CONFIRM to proceed.
import { el, replace } from '../dom.js'
import { recordSigning } from './history.js'

const LEVEL_ICON = { danger: '⛔', warn: '⚠', info: 'ℹ', safe: '✓' }

export function confirmSign({ heading, action, verdict, digests, balanceChanges = [], meta = [], context = {} }) {
  return new Promise((resolve) => {
    const proceed = el('button', { disabled: verdict.blocked }, 'Confirm on device')
    const cancel = el('button', { class: 'ghost' }, 'Cancel')
    const finish = (v) => {
      overlay.remove()
      recordSigning({
        kind: action.kind, title: action.title,
        outcome: v ? 'approved' : (verdict.blocked ? 'blocked-then-cancelled' : 'rejected'),
        account: context.account, chainId: context.chainId, asset: context.asset,
        worst: verdict.worst, findings: verdict.findings,
      })
      resolve(v)
    }
    proceed.addEventListener('click', () => finish(true))
    cancel.addEventListener('click', () => finish(false))

    const typeBox = verdict.blocked
      ? el('div', { class: 'sig-typebox' },
          el('label', {}, 'This request is dangerous. Type CONFIRM to enable signing.'),
          el('input', {
            placeholder: 'CONFIRM',
            oninput: (e) => { proceed.disabled = e.target.value.trim().toUpperCase() !== 'CONFIRM' },
          }))
      : null

    const overlay = el('div', { class: 'sig-overlay' },
      el('div', { class: `sig-sheet ${verdict.worst}`, onclick: (e) => e.stopPropagation() },
        el('div', { class: 'sig-head' },
          el('div', { class: 'sig-kicker' }, heading),
          el('div', { class: 'sig-title' }, action.title),
          action.plain ? el('div', { class: 'sig-plain' }, action.plain) : null),

        verdict.findings.length
          ? el('div', { class: 'sig-findings' }, verdict.findings.map((f) =>
              el('div', { class: `sig-finding ${f.level}` },
                el('span', { class: 'ic' }, LEVEL_ICON[f.level]),
                el('span', {}, f.text))))
          : null,

        balanceChanges.length
          ? el('div', { class: 'sig-section' },
              el('div', { class: 'sig-sec-title' }, 'Balance changes'),
              balanceChanges.map((b) =>
                el('div', { class: `sig-bal ${b.direction}` },
                  el('span', {}, b.direction === 'out' ? '−' : '+'),
                  el('span', { class: 'what' }, b.what),
                  el('span', { class: 'who' }, b.detail || ''))))
          : null,

        action.fields?.length
          ? el('div', { class: 'sig-section' },
              el('div', { class: 'sig-sec-title' }, 'Details'),
              action.fields.map((f) => el('div', { class: 'sig-kv' },
                el('span', { class: 'k' }, f.k), el('span', { class: 'v' }, String(f.v)))))
          : null,

        meta.length
          ? el('div', { class: 'sig-section' }, meta.map((m) => el('div', { class: 'sig-kv' },
              el('span', { class: 'k' }, m.k), el('span', { class: 'v' }, String(m.v)))))
          : null,

        digests
          ? el('div', { class: 'sig-section digests' },
              el('div', { class: 'sig-sec-title' }, 'Verify on your KeepKey screen'),
              el('div', { class: 'sig-kv' }, el('span', { class: 'k' }, 'domain'), el('span', { class: 'v mono' }, digests.domainSep.slice(2))),
              el('div', { class: 'sig-kv' }, el('span', { class: 'k' }, 'message'), el('span', { class: 'v mono' }, digests.structHash.slice(2))),
              el('div', { class: 'sig-note' }, 'These two hashes are computed by this page, independently of Vault. The device must show the same values — if not, reject on the device.'))
          : null,

        typeBox,
        el('div', { class: 'sig-actions' }, cancel, proceed)))

    overlay.addEventListener('click', () => finish(false))
    document.body.append(overlay)
  })
}
