// Rule engine: decoded action + context → leveled findings.
// Modeled on Rabby's rabby-security-engine (MIT): small, ordered, auditable
// rules; each returns null or { level, code, text }. Levels: danger | warn |
// info | safe. UI blocks (requires typed confirmation) on any danger.
import { getAddress, isAddress } from 'viem'
import { checkUrl } from '../blocklist.js'
import { labelFor } from '../labels.js'

const eq = (a, b) => a && b && String(a).toLowerCase() === String(b).toLowerCase()
const BURN = ['0x0000000000000000000000000000000000000000', '0x000000000000000000000000000000000000dead']

// ctx: { action, chainId, ownerAddress, knownAddresses[], recipientIsNew,
//        recipientCode, activeProofs, originUrl, feeEth, nftName }
export async function evaluate(ctx) {
  const f = []
  const a = ctx.action || {}

  // --- destination safety ---------------------------------------------
  if (a.kind === 'nft-transfer' || a.kind === 'token-transfer') {
    const to = a.to
    if (BURN.includes(String(to).toLowerCase())) {
      f.push({ level: 'danger', code: 'burn-address', text: 'Recipient is a burn address — the asset would be destroyed permanently.' })
    } else if (isAddress(String(to || ''))) {
      if (eq(to, ctx.ownerAddress)) {
        f.push({ level: 'info', code: 'self-transfer', text: 'Sending to yourself. This revokes outstanding display proofs without giving the NFT away.' })
      } else if (ctx.knownAddresses?.some((k) => eq(k, to))) {
        f.push({ level: 'safe', code: 'own-account', text: 'Recipient is another account on this same KeepKey.' })
      } else {
        f.push({ level: ctx.recipientIsNew ? 'warn' : 'info', code: 'external-recipient',
          text: 'Recipient is an external address. Transfers are irreversible — confirm the address character by character.' })
      }
      if (ctx.recipientCode && ctx.recipientCode !== '0x') {
        f.push({ level: 'warn', code: 'contract-recipient', text: 'Recipient is a smart contract, not a wallet. If it cannot handle NFTs, the asset may be stuck forever.' })
      }
    }
    if (ctx.activeProofs > 0) {
      f.push({ level: 'warn', code: 'kills-proofs', text: `This transfer invalidates ${ctx.activeProofs} active display proof(s) for this NFT.` })
    }
  }

  // --- approvals: the drainer's favorite -------------------------------
  if (a.kind === 'approve-all' && a.approved) {
    const lbl = labelFor(a.operator, { accounts: ctx.knownAddresses?.map((x, i) => ({ address: x, index: i })) })
    f.push({ level: 'danger', code: 'approve-all',
      text: `Grants ${lbl ? `"${lbl.text}"` : 'an operator'} permission to move EVERY NFT you own in this collection, now and in the future. This is the most abused permission in NFT theft.` })
    if (lbl?.tier === 'known') {
      f.push({ level: 'info', code: 'known-operator', text: `The operator is recognized infrastructure (${lbl.text}) — expected when listing on that marketplace, suspicious anywhere else.` })
    }
  }
  if (a.kind === 'approve') {
    f.push({ level: 'warn', code: 'approve-single', text: 'Grants a spender permission over this asset until revoked.' })
  }
  if (a.kind === 'permit' || a.kind === 'permit-signature') {
    f.push({ level: 'danger', code: 'permit',
      text: 'A permit signature lets someone spend your tokens with no further approval. Drainers use these because they look harmless.' })
  }
  if (a.kind === 'marketplace-order') {
    const o = a.order
    if (o?.isGiveaway) {
      f.push({ level: 'danger', code: 'giveaway-order',
        text: `This order gives away ${o.givingNftCount} item(s) and returns NOTHING. This is the classic NFT-drainer signature — anyone could fulfil it and take them for free.` })
    } else {
      f.push({ level: 'danger', code: 'marketplace-order',
        text: 'This order signature can transfer your NFTs when fulfilled. Verify the marketplace and the price you set.' })
    }
    if (o?.anyCriteria) {
      f.push({ level: 'danger', code: 'criteria-order',
        text: 'This is a criteria order: it covers ANY token in the collection, not one specific NFT.' })
    }
    if (o?.durationDays > 30) {
      f.push({ level: 'warn', code: 'long-order',
        text: `This order stays fulfillable for ${Math.round(o.durationDays)} days. Cancel it on-chain if you change your mind.` })
    }
    if (o?.offerer && ctx.ownerAddress && o.offerer.toLowerCase() !== String(ctx.ownerAddress).toLowerCase()) {
      f.push({ level: 'danger', code: 'offerer-mismatch',
        text: `The order's offerer (${o.offerer.slice(0, 10)}…) is not the account you are signing with. Do not sign.` })
    }
  }
  if (a.kind === 'unknown' || a.kind === 'typed-unknown') {
    f.push({ level: 'warn', code: 'undecodable',
      text: 'This wallet cannot decode this request. Compare the digests on your KeepKey screen and reject if anything looks off.' })
  }

  // --- our own known-good pattern ---------------------------------------
  if (a.kind === 'display-authorization') {
    f.push({ level: 'safe', code: 'known-pattern', text: 'Known pattern: KeepKey display authorization. It cannot move, sell, or spend any asset.' })
    const days = (a.expiresAt - Math.floor(Date.now() / 1000)) / 86400
    if (days > 14) f.push({ level: 'warn', code: 'long-window', text: `Long validity (${Math.round(days)} days). Proofs cannot be revoked before expiry except by moving the NFT.` })
  }

  // --- origin / phishing --------------------------------------------------
  if (ctx.originUrl) {
    const v = await checkUrl(ctx.originUrl)
    if (v.verdict === 'blocked') f.push({ level: 'danger', code: 'phishing-origin', text: `Request origin flagged as phishing: ${v.reason}` })
    else if (v.verdict === 'fuzzy') f.push({ level: 'danger', code: 'lookalike-origin', text: `Origin looks like a spoofed domain: ${v.reason}` })
  }
  if (ctx.nftName) {
    const { checkTextForDomains } = await import('../blocklist.js')
    const v = await checkTextForDomains(ctx.nftName)
    if (v.verdict !== 'ok') f.push({ level: 'danger', code: 'phishing-in-metadata', text: `This NFT's name contains a known phishing domain (${v.host}). It is bait — do not visit it.` })
  }

  // --- simulation ---------------------------------------------------------
  if (ctx.simulation) {
    if (ctx.simulation.ok === false) {
      f.push({ level: 'danger', code: 'simulation-failed',
        text: `Simulation says this transaction would FAIL: ${ctx.simulation.revertReason || 'reverted'}. Signing it would waste gas and change nothing.` })
    } else {
      f.push({ level: 'safe', code: 'simulation-ok', text: 'Simulated against current chain state: this transaction would succeed.' })
    }
    if (ctx.simulation.note) f.push({ level: 'info', code: 'simulation-note', text: ctx.simulation.note })
  }

  // --- economics ----------------------------------------------------------
  if (ctx.feeEth != null && Number(ctx.feeEth) > 0.02) {
    f.push({ level: 'warn', code: 'high-fee', text: `Network fee is high (≈${Number(ctx.feeEth).toFixed(4)} ETH). Consider waiting for cheaper gas.` })
  }

  const order = { danger: 0, warn: 1, info: 2, safe: 3 }
  f.sort((x, y) => order[x.level] - order[y.level])
  return { findings: f, worst: f.length ? f[0].level : 'info', blocked: f.some((x) => x.level === 'danger') }
}
