// Data-driven spam ruleset.
//
// Rules live in public/rules/spam-rules.json and are fetched from OUR OWN
// origin at runtime, so a new scam pattern ships as a reviewed data update
// instead of a release. The bundled defaults (rules/defaults.js) are the
// safety net: if the fetch fails, is malformed, or is older than what we
// shipped, the user keeps full protection.
//
// SECURITY: patterns arrive as strings and are compiled into RegExp. Even
// though the source is same-origin, we treat the ruleset as untrusted input:
// patterns are length-capped, screened for catastrophic-backtracking shapes,
// compiled in isolation, and every scanned string is truncated. A bad rule
// is dropped, never thrown.
import { DEFAULT_RULESET } from './defaults.js'

// Brand/lure rules legitimately need long alternations. Inputs are capped at
// MAX_INPUT and alternations scan linearly, so the cost stays bounded.
const MAX_PATTERN = 900
const MAX_INPUT = 400
const MAX_RULES = 200

// Nested quantifiers like (a+)+ or (a*)* are the classic ReDoS shape.
const REDOS = /\([^)]*[+*]\)[+*{]|\([^)]*\{\d+,\}\)[+*{]/

export function compileRule(raw) {
  if (!raw || typeof raw.code !== 'string' || typeof raw.weight !== 'number') return null
  if (typeof raw.why !== 'string' || raw.weight < 0 || raw.weight > 20) return null
  if (raw.pattern !== undefined) {
    if (typeof raw.pattern !== 'string' || raw.pattern.length > MAX_PATTERN) return null
    if (REDOS.test(raw.pattern)) return null
    let re
    try { re = new RegExp(raw.pattern, typeof raw.flags === 'string' ? raw.flags.replace(/[^gimsuy]/g, '') : 'i') }
    catch { return null }
    return { ...raw, re }
  }
  // no pattern → must name a built-in predicate, resolved by the caller
  return typeof raw.predicate === 'string' ? { ...raw } : null
}

export function compileRuleset(json) {
  if (!json || !Array.isArray(json.rules)) return null
  const rules = json.rules.slice(0, MAX_RULES).map(compileRule).filter(Boolean)
  if (!rules.length) return null
  return {
    version: String(json.version ?? '0'),
    updated: String(json.updated ?? ''),
    threshold: Number.isFinite(json.threshold) ? json.threshold : 4,
    rules,
  }
}

let active = compileRuleset(DEFAULT_RULESET)
let loading = null

export const activeRuleset = () => active

// Fetch the hosted ruleset; keep whichever version is higher so a stale or
// rolled-back file can never downgrade protection.
export function loadRuleset() {
  return (loading ??= fetch(new URL('rules/spam-rules.json', document.baseURI))
    .then((r) => (r.ok ? r.json() : null))
    .then((json) => {
      const next = compileRuleset(json)
      if (next && Number(next.version) >= Number(active.version)) active = next
      return active
    })
    .catch(() => active))
}

// fields: { name, collection, description, externalUrl }
export function evaluateRules(fields, predicates, nft) {
  const text = {
    name: String(fields.name || '').slice(0, MAX_INPUT),
    collection: String(fields.collection || '').slice(0, MAX_INPUT),
    both: `${fields.name || ''} ${fields.collection || ''}`.slice(0, MAX_INPUT),
    description: String(fields.description || '').slice(0, MAX_INPUT),
    all: `${fields.name || ''} ${fields.collection || ''} ${fields.description || ''} ${fields.externalUrl || ''}`.slice(0, MAX_INPUT),
  }
  const hits = []
  for (const rule of active.rules) {
    let hit = false
    try {
      if (rule.re) {
        const target = text[rule.on || 'both'] ?? text.both
        hit = rule.re.test(target)
        if (hit && rule.unless && predicates[rule.unless]?.(nft)) hit = false
      } else {
        hit = !!predicates[rule.predicate]?.(nft)
      }
    } catch { hit = false }
    if (hit) hits.push(rule)
  }
  return hits
}
