import QRCode from 'qrcode'
import { el } from '../dom.js'
import { proofUrl } from '../flex.js'

export async function showQr({ text, title, sub, copyText }) {
  const qr = await QRCode.toDataURL(text, { width: 520, margin: 1, color: { dark: '#111111', light: '#ffffff' } })
  const toCopy = copyText ?? text
  const copyBtn = el('button', {
    onclick: () => { navigator.clipboard.writeText(toCopy); copyBtn.textContent = 'Copied!' },
  }, 'Copy')
  const overlay = el('div', { class: 'modal', onclick: () => overlay.remove() },
    el('div', { class: 'sheet', onclick: (e) => e.stopPropagation() },
      el('img', { src: qr, alt: title }),
      el('div', { class: 't' }, title),
      el('div', { class: 's' }, sub),
      copyBtn))
  document.body.append(overlay)
}

export const showQrModal = (bundle) =>
  showQr({ text: proofUrl(bundle), title: 'Verified Flex', sub: 'Scan to verify this NFT is hardware-owned' })
