// Local signing history. Every request that reaches the confirmation sheet is
// recorded — approved, rejected, or blocked — so "what did I sign, and when?"
// has an answer. Wallets that lack this leave users unable to reconstruct a
// compromise after the fact.
//
// Local-only: never transmitted, capped, and clearable.
const KEY = 'kk_sign_history'
const MAX = 200

export const loadHistory = () => {
  try { return JSON.parse(localStorage.getItem(KEY) || '[]') } catch { return [] }
}

export function recordSigning(entry) {
  const rows = loadHistory()
  rows.unshift({
    at: Date.now(),
    kind: entry.kind || 'unknown',
    title: entry.title || '',
    outcome: entry.outcome,               // approved | rejected | blocked
    account: entry.account || null,
    chainId: entry.chainId ?? null,
    asset: entry.asset || null,
    worst: entry.worst || 'info',         // highest finding level shown
    findings: (entry.findings || []).map((f) => f.code).slice(0, 8),
  })
  localStorage.setItem(KEY, JSON.stringify(rows.slice(0, MAX)))
}

export const clearHistory = () => localStorage.removeItem(KEY)
