// NFT discovery via keyless Blockscout APIs. Everything returned by these
// endpoints is UNTRUSTED (names, metadata, URLs) — render as text only,
// resolve images defensively.
import { CHAINS, IPFS_GATEWAYS, SPAM } from './config.js'

export const keyOf = (n) => `${n.chainId}:${(n.contract || '').toLowerCase()}:${n.tokenId}`

// Extract an IPFS path from possibly percent-encoded, wrapped URLs and return
// gateway candidates; plain https URLs pass through. Anything else (data:,
// javascript:, ipfs-less garbage) resolves to no image at all.
export function imageCandidates(...urls) {
  for (let u of urls.filter(Boolean)) {
    u = String(u)
    try { u = decodeURIComponent(u) } catch { /* keep raw */ }
    const m = u.match(/ipfs:\/\/([^"'\s&]+)/) || u.match(/\/ipfs\/([^"'\s?&]+)/)
    if (m) return IPFS_GATEWAYS.map((g) => g + m[1])
    if (/^https:\/\//.test(u)) return [u]
  }
  return []
}

// Ask the indexer to re-read tokenURI from chain (metadata changes after
// reveals, or arrives late). Best-effort: not all Blockscout instances
// expose it, and a failure is not user-visible beyond "nothing changed".
export async function refreshMetadata(nft) {
  const chain = CHAINS.find((c) => c.id === nft.chainId)
  if (!chain) return false
  try {
    const r = await fetch(`${chain.scout}/api/v2/tokens/${nft.contract}/instances/${nft.tokenId}/refetch-metadata`, { method: 'PATCH' })
    return r.ok
  } catch { return false }
}

export async function fetchInstance(nft) {
  const chain = CHAINS.find((c) => c.id === nft.chainId)
  if (!chain) return null
  try {
    const r = await fetch(`${chain.scout}/api/v2/tokens/${nft.contract}/instances/${nft.tokenId}`)
    if (!r.ok) return null
    const it = await r.json()
    return {
      name: it.metadata?.name || nft.name,
      images: imageCandidates(it.image_url, it.metadata?.image, it.metadata?.image_url),
      attributes: Array.isArray(it.metadata?.attributes) ? it.metadata.attributes.slice(0, 12) : [],
    }
  } catch { return null }
}

export async function scanChain(chain, account, onError) {
  try {
    // paginate up to 4 pages (200 items) per account/chain
    const items = []
    let query = '?type=ERC-721%2CERC-1155'
    for (let page = 0; page < 4 && query; page++) {
      const r = await fetch(`${chain.scout}/api/v2/addresses/${account.address}/nft${query}`)
      if (!r.ok) break
      const j = await r.json()
      items.push(...(j.items || []))
      query = j.next_page_params ? '?type=ERC-721%2CERC-1155&' + new URLSearchParams(j.next_page_params).toString() : null
    }
    return items.map((it) => {
      const name = it.metadata?.name || `${it.token?.name || '?'} #${it.id}`
      return {
        chainId: chain.id, chainName: chain.name,
        contract: it.token?.address_hash || it.token?.address,
        tokenId: String(it.id),
        name: String(name).slice(0, 120),
        collectionName: it.token?.name ? String(it.token.name).slice(0, 60) : null,
        collectionSymbol: it.token?.symbol ? String(it.token.symbol).slice(0, 20) : null,
        description: it.metadata?.description ? String(it.metadata.description).slice(0, 400) : null,
        externalUrl: it.metadata?.external_url || null,
        standard: it.token?.type,
        // ERC-1155 balance (how many copies this account holds)
        quantity: it.value ? String(it.value) : null,
        // Blockscout's own scam flag, in addition to our heuristics
        flaggedScam: !!it.token?.is_scam,
        images: imageCandidates(it.image_url, it.metadata?.image, it.metadata?.image_url),
        attributes: Array.isArray(it.metadata?.attributes) ? it.metadata.attributes.slice(0, 12) : [],
        spam: !!it.token?.is_scam || SPAM.test(it.token?.name || '') || SPAM.test(String(name)),
        owner: account.address, ownerIndex: account.index,
      }
    }).filter((n) => n.contract)
  } catch (e) {
    onError?.(chain, account, e)
    return []
  }
}

// Returns { nfts, errors } — indexer flakiness must be visible, not silent:
// an empty gallery caused by a failing API looks identical to "you own
// nothing", which is exactly the confusion that hides real assets.
export async function scanAll(accounts, onProgress) {
  const errors = []
  const results = await Promise.all(accounts.flatMap((a) => CHAINS.map(async (c) => {
    const out = await scanChain(c, a, (chain, acct, e) => errors.push(`${chain.name}/#${acct.index}: ${e.message || e}`))
    onProgress?.(a, c, out.length)
    return out
  })))
  return { nfts: results.flat(), errors }
}
