// Spam scoring. SimpleHash (the industry's spam-score API) shut down in
// March 2025, so this is our own transparent stack rather than an opaque
// third-party score. Every signal is explainable to the user, because a
// false positive hides a real asset.
//
// The RULES are data (src/rules/defaults.js, overridable at runtime by
// public/rules/spam-rules.json). This file holds only the built-in
// predicates — the checks a regex cannot express — plus the scoring loop.
import { checkTextForDomains } from './blocklist.js'
import { evaluateRules, activeRuleset, loadRuleset } from './rules/engine.js'

export { loadRuleset, activeRuleset }
export const SPAM_THRESHOLD = 4   // bundled default; the ruleset may override

// Domain-name NFTs (ENS, Unstoppable) legitimately have a domain AS the name.
const DOMAIN_COLLECTION = /unstoppable domains|ethereum name service|\bens\b|name service|\.bit\b|space id/i
// PFP collections that only exist on Ethereum mainnet; the same name on
// another chain is an impersonation, no lure word required.
const ETHEREUM_ONLY = /pudgy|azuki|boredape|bored ape|mutant ape|veefriends|doodles|moonbird|clonex|cryptopunk|meebit/i
const IMPERSONATED = /veefriends|boredape|yuga|azuki|pudgy|doodles|moonbird|clonex|opensea|uniswap|shiba|pancakeswap|lido|st\.?eth|laye?r ?zero|arbitrum|optimism|blur|metamask|ledger|trezor|coinbase|binance/i

const both = (n) => `${n.name || ''} ${n.collectionName || ''}`

// Random-string collection names (base64-ish IDs) are throwaway contracts.
const gibberish = (s) => {
  if (!s || /\s/.test(s) || s.length < 12) return false
  const letters = s.replace(/[^a-zA-Z]/g, '')
  if (letters.length < 10) return false
  const flips = [...letters].filter((c, i, a) => i && (c === c.toUpperCase()) !== (a[i - 1] === a[i - 1].toUpperCase())).length
  return flips / letters.length > 0.25
}

export const PREDICATES = {
  flaggedScam: (n) => !!n.flaggedScam,
  anonymousContract: (n) => !n.collectionName && !n.collectionSymbol,
  namedCollection: (n) => !!n.collectionName,
  domainCollection: (n) => DOMAIN_COLLECTION.test(n.collectionName || ''),
  anonymousImpersonation: (n) => !n.collectionName &&
    IMPERSONATED.test(`${n.name} ${n.description || ''} ${n.externalUrl || ''}`),
  wrongChainBrand: (n) => ETHEREUM_ONLY.test(both(n)) && Number(n.chainId) !== 1,
  gibberishCollection: (n) => gibberish(n.collectionName),
  emojiSpam: (n) => ((String(n.name || '').match(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu) || []).length >= 3),
  noImage: (n) => !n.images?.length,
  shouty: (n) => String(n.name || '').length > 12 && n.name === n.name.toUpperCase(),
}

export async function scoreNft(n) {
  const hits = evaluateRules(
    { name: n.name, collection: n.collectionName, description: n.description, externalUrl: n.externalUrl },
    PREDICATES, n,
  )
  let score = hits.reduce((s, r) => s + r.weight, 0)
  const reasons = hits.map((r) => r.why)

  // a known phishing domain in the text is decisive
  const dom = await checkTextForDomains(both(n))
  if (dom.verdict === 'blocked' || dom.verdict === 'fuzzy') {
    score += 6
    reasons.unshift(`contains known phishing domain (${dom.host})`)
  }
  return { score, spam: score >= activeRuleset().threshold, reasons }
}

export async function scoreAll(nfts) {
  await loadRuleset()   // pick up hosted rules before scoring a batch
  return Promise.all(nfts.map(async (n) => {
    const { score, spam, reasons } = await scoreNft(n)
    return { ...n, spamScore: score, spam: spam || n.spam, spamReasons: reasons }
  }))
}
